def R(x, y, w, h):
    return {"x": x, "y": y, "w": w, "h": h}

def clue(kind, title, explanation, region=None):
    return {"kind": kind, "title": title, "explanation": explanation, "region": region}

SRC_AI = lambda gen: clue("source", "The uploader names the AI tool",
    f"The Commons page says this picture was made with {gen} and files it in an AI-generated images category. There is no photographer, camera or place behind it.")

def cam(m):
    return clue("metadata", "Traceable photographer and camera",
        f"The original file on Commons records the camera ({m['make'].strip()} {m['model'].strip()}) and a named photographer, and it was uploaded in {m['ts'][:4]}, before photo-realistic AI image tools existed.")

