out = []
for slug, (lk, attribution, generator, aset, prov, cluefn) in ITEMS.items():
    m = meta[slug]
    assert not m["problems"], slug
    lic, lurl = CC[lk]
    out.append({
        "slug": slug, "mediaType": "image", "mediaUrl": f"/media/items/{slug}.jpg",
        "width": m["width"], "height": m["height"], "label": m["label"], "category": m["category"],
        "sourceName": "Wikimedia Commons", "sourceUrl": m["page"], "license": lic, "licenseUrl": lurl,
        "attribution": attribution, "generator": generator, "provenanceNote": prov,
        "assessmentSet": aset, "status": "published", "reviewStatus": "ai_draft", "clues": cluefn(m),
    })
assert len(out) == len(meta) == 48
path = os.path.join(HERE, "..", "seed", "items.json")
json.dump(out, open(path, "w"), ensure_ascii=False, indent=2)
open(path, "a").write("\n")
print("wrote", len(out), "items")
